package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

const BUFFER_SIZE = 1 << 16

type FastIO struct {
	din           io.Reader
	buffer        []byte
	bufferPointer int
	bytesRead     int
}

func NewFastIO(inputStream io.Reader) *FastIO {
	return &FastIO{
		din:           inputStream,
		buffer:        make([]byte, BUFFER_SIZE),
		bufferPointer: 0,
		bytesRead:     0,
	}
}

func (f *FastIO) fillBuffer() {
	f.bufferPointer = 0
	n, err := f.din.Read(f.buffer)
	if err != nil && n <= 0 {
		f.bytesRead = -1
		f.buffer[0] = 255
		return
	}
	f.bytesRead = n
	if f.bytesRead == -1 {
		f.buffer[0] = 255
	}
}

func (f *FastIO) read() int8 {
	if f.bufferPointer == f.bytesRead {
		f.fillBuffer()
	}
	b := int8(f.buffer[f.bufferPointer])
	f.bufferPointer++
	return b
}

func (f *FastIO) nextInt() int {
	ret := 0
	c := f.read()
	for c <= ' ' {
		c = f.read()
	}
	neg := c == '-'
	if neg {
		c = f.read()
	}
	for {
		ret = ret*10 + int(c) - '0'
		c = f.read()
		if !(c >= '0' && c <= '9') {
			break
		}
	}
	if neg {
		return -ret
	}
	return ret
}

func (f *FastIO) nextIntArray(n int) []int {
	arr := make([]int, n)
	for i := 0; i < n; i++ {
		arr[i] = f.nextInt()
	}
	return arr
}

type TaskA1 struct{}

func (t *TaskA1) solve(testNumber int, in *FastIO, out *bufio.Writer) {
	n := in.nextInt()
	k := in.nextInt()
	query := in.nextIntArray(n)
	cost := 0
	availableBooks := make(map[int]bool, k)
	access := make([]int, 81)
	removable := -1
	for i := 0; i < n; i++ {
		access[query[i]]++
	}
	for i := 0; i < n; i++ {
		currentBook := query[i]
		doesNotContain := !availableBooks[currentBook]
		if doesNotContain {
			cost++
		}
		if removable != -1 {
			delete(availableBooks, removable)
			removable = -1
		} else if len(availableBooks) == k && doesNotContain {
			removableBook := -1
			count := k
			known := make(map[int]bool)
			for j := i + 1; j < n && count > 0; j++ {
				if availableBooks[query[j]] && !known[query[j]] {
					count--
					known[query[j]] = true
					removableBook = query[j]
				}
			}
			if removableBook != -1 {
				delete(availableBooks, removableBook)
			} else {
				for key := range availableBooks {
					delete(availableBooks, key)
					break
				}
			}
		}
		availableBooks[currentBook] = true
		access[currentBook]--
		if access[currentBook] == 0 {
			removable = currentBook
		}
	}
	fmt.Fprintln(out, cost)
}

func main() {
	in := NewFastIO(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	solver := &TaskA1{}
	solver.solve(1, in, out)
}
